`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is asserted on cycle 0 so k-induction starts from a valid state
    always @(*) if (!f_past_valid) assume(!rst_n);

    always @(posedge clk) begin
        // P_RST_VALID_LOW: valid_o must be 0 immediately after reset
        if (f_past_valid && $past(!rst_n)) begin
            P_RST_VALID_LOW: assert(valid_o == 1'b0);
        end
        // P_RST_RESULT_ZERO: result_o must be 0 immediately after reset
        if (f_past_valid && $past(!rst_n)) begin
            P_RST_RESULT_ZERO: assert(result_o == 32'd0);
        end
        // P_ZERO_FLAG_CONSISTENT: zero_o must match (result_o == 0) whenever valid_o is asserted
        if (f_past_valid && rst_n && (valid_o)) begin
            P_ZERO_FLAG_CONSISTENT: assert((zero_o == (result_o == 32'd0)));
        end
        // C_REACH_VALID_OUT: Prove non-vacuous reachability of a non-zero valid ALU result
        if (f_past_valid && rst_n) begin
            C_REACH_VALID_OUT: cover(valid_o && (result_o != 32'd0));
        end
    end
`endif
